@* Step indicator bar showing progress through the wizard *@

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <div class="text-center flex-fill position-relative">
                @if (step > 0)
                {
                    <div class="step-connector @(isCompleted ? "bg-success" : "bg-secondary")"
                         style="position:absolute;top:18px;left:-50%;right:50%;height:3px;z-index:0;"></div>
                }

                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center border-0
                               @(isCompleted ? "bg-success text-white" : isCurrent ? "bg-primary text-white" : "bg-light text-muted border")"
                        style="width:36px;height:36px;z-index:1;position:relative;font-size:0.85rem;"
                        disabled="@(isFuture)"
                        @onclick="() => OnStepClicked.InvokeAsync(step)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </button>

                <div class="mt-1 small @(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                    @StepNames[step]
                </div>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public List<string> StepNames { get; set; } = [];

    [Parameter]
    public EventCallback<int> OnStepClicked { get; set; }
}

@using sv_c78a5efcdae744cdb38ca63f432bfadd.Models

<h4 class="mb-3">Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input class="form-control" @bind="FullName" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control @(emailInvalid ? "is-invalid" : "")" @bind="Email" />
        @if (emailInvalid)
        {
            <div class="invalid-feedback">Please enter a valid email address.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control" @bind="Phone" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input class="form-control" @bind="Address" />
    </div>
</div>

<div class="d-flex justify-content-end mt-4">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
        @if (isValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool emailInvalid;
    private bool isValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        emailInvalid = false;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            isValidating = true;
            StateHasChanged();

            var valid = await ValidateEmail(Email);
            isValidating = false;

            if (!valid)
            {
                emailInvalid = true;
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@using sv_c78a5efcdae744cdb38ca63f432bfadd.Models

<h4 class="mb-3">Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <WorkEntryEditor Position="@(index + 1)"
                     Company="@entry.Company"
                     Title="@entry.Title"
                     StartDate="@entry.StartDate"
                     EndDate="@entry.EndDate"
                     IsCurrent="@(entry.EndDate is null && !string.IsNullOrEmpty(entry.Company))"
                     Description="@entry.Description"
                     CanRemove="@(Entries.Count > 1)"
                     OnChanged="(data) => HandleEntryChanged(index, data)"
                     OnRemove="() => HandleRemove(index)" />
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<EntryModel> Entries { get; set; } = [new()];
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    public class EntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }

    private void HandleEntryChanged(int index, WorkEntryEditor.WorkEntryData data)
    {
        if (index < Entries.Count)
        {
            Entries[index] = new EntryModel
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                Description = data.Description
            };
        }
    }

    private void HandleRemove(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void AddEntry()
    {
        Entries.Add(new EntryModel());
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        var firstEntry = Entries[0];
        if (string.IsNullOrWhiteSpace(firstEntry.Company) || string.IsNullOrWhiteSpace(firstEntry.Title))
        {
            ErrorMessage = "At least one work entry with company name and job title is required.";
            return;
        }

        var workEntries = Entries
            .Where(e => !string.IsNullOrWhiteSpace(e.Company))
            .Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description))
            .ToList();

        await OnNext.InvokeAsync(workEntries);
    }
}

@using sv_c78a5efcdae744cdb38ca63f432bfadd.Models

<h4 class="mb-3">References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Refs.Count; i++)
{
    var index = i;
    var r = Refs[index];

    <ReferenceEditor Position="@(index + 1)"
                     Name="@r.Name"
                     Relationship="@r.Relationship"
                     Email="@r.Email"
                     Phone="@r.Phone"
                     CanRemove="@(Refs.Count > 2)"
                     OnChanged="(data) => HandleChanged(index, data)"
                     OnRemove="() => HandleRemove(index)" />
}

@if (Refs.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<RefModel> Refs { get; set; } = [new(), new()];
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    public class RefModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void HandleChanged(int index, ReferenceEditor.ReferenceData data)
    {
        if (index < Refs.Count)
        {
            Refs[index] = new RefModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private void HandleRemove(int index)
    {
        if (Refs.Count > 2)
        {
            Refs.RemoveAt(index);
        }
    }

    private void AddReference()
    {
        if (Refs.Count < 3)
        {
            Refs.Add(new RefModel());
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (Refs.Count < 2 || Refs.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            ErrorMessage = "At least 2 references with name and email are required.";
            return;
        }

        var references = Refs
            .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();

        await OnNext.InvokeAsync(references);
    }
}

