@using sv_c78a5efcdae744cdb38ca63f432bfadd.Models

<h4 class="mb-3">Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <WorkEntryEditor Position="@(index + 1)"
                     Company="@entry.Company"
                     Title="@entry.Title"
                     StartDate="@entry.StartDate"
                     EndDate="@entry.EndDate"
                     IsCurrent="@(entry.EndDate is null && !string.IsNullOrEmpty(entry.Company))"
                     Description="@entry.Description"
                     CanRemove="@(Entries.Count > 1)"
                     OnChanged="(data) => HandleEntryChanged(index, data)"
                     OnRemove="() => HandleRemove(index)" />
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<EntryModel> Entries { get; set; } = [new()];
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    public class EntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }

    private void HandleEntryChanged(int index, WorkEntryEditor.WorkEntryData data)
    {
        if (index < Entries.Count)
        {
            Entries[index] = new EntryModel
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                Description = data.Description
            };
        }
    }

    private void HandleRemove(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void AddEntry()
    {
        Entries.Add(new EntryModel());
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        var firstEntry = Entries[0];
        if (string.IsNullOrWhiteSpace(firstEntry.Company) || string.IsNullOrWhiteSpace(firstEntry.Title))
        {
            ErrorMessage = "At least one work entry with company name and job title is required.";
            return;
        }

        var workEntries = Entries
            .Where(e => !string.IsNullOrWhiteSpace(e.Company))
            .Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description))
            .ToList();

        await OnNext.InvokeAsync(workEntries);
    }
}

