@using sv_c78a5efcdae744cdb38ca63f432bfadd.Models

<h4 class="mb-3">References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Refs.Count; i++)
{
    var index = i;
    var r = Refs[index];

    <ReferenceEditor Position="@(index + 1)"
                     Name="@r.Name"
                     Relationship="@r.Relationship"
                     Email="@r.Email"
                     Phone="@r.Phone"
                     CanRemove="@(Refs.Count > 2)"
                     OnChanged="(data) => HandleChanged(index, data)"
                     OnRemove="() => HandleRemove(index)" />
}

@if (Refs.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<RefModel> Refs { get; set; } = [new(), new()];
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    public class RefModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void HandleChanged(int index, ReferenceEditor.ReferenceData data)
    {
        if (index < Refs.Count)
        {
            Refs[index] = new RefModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private void HandleRemove(int index)
    {
        if (Refs.Count > 2)
        {
            Refs.RemoveAt(index);
        }
    }

    private void AddReference()
    {
        if (Refs.Count < 3)
        {
            Refs.Add(new RefModel());
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (Refs.Count < 2 || Refs.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            ErrorMessage = "At least 2 references with name and email are required.";
            return;
        }

        var references = Refs
            .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();

        await OnNext.InvokeAsync(references);
    }
}

