@page "/apply"
@using sv_c78a5efcdae744cdb38ca63f432bfadd.Models
@using sv_c78a5efcdae744cdb38ca63f432bfadd.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   StepNames="@stepNames"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                                  ValidateEmail="AppService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="@workEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep Refs="@referenceModels"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep Text="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep @ref="reviewStepRef"
                            Personal="@personalInfo!"
                            WorkEntries="@workHistory"
                            References="@references"
                            CoverLetter="@coverLetter"
                            OnBack="GoBack"
                            OnEditSection="GoToStep"
                            OnSubmit="HandleSubmit" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private ReviewStep? reviewStepRef;

    private readonly List<string> stepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private PersonalInfo? personalInfo;

    // Step 2 state
    private List<WorkHistoryStep.EntryModel> workEntries = [new()];
    private List<WorkEntry> workHistory = [];

    // Step 3 state
    private List<ReferencesStep.RefModel> referenceModels = [new(), new()];
    private List<Reference> references = [];

    // Step 4 state
    private string coverLetter = "";

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        fullName = info.FullName;
        email = info.Email;
        phone = info.Phone;
        address = info.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        workHistory = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(personalInfo!, new WorkHistory(workHistory), references, coverLetter);

        try
        {
            var id = await AppService.SubmitApplicationAsync(application);

            if (reviewStepRef is not null)
            {
                reviewStepRef.IsSubmitting = false;
                reviewStepRef.Submitted = true;
                reviewStepRef.ApplicationId = id;
            }
        }
        catch (Exception ex)
        {
            if (reviewStepRef is not null)
            {
                reviewStepRef.IsSubmitting = false;
                reviewStepRef.ErrorMessage = $"Submission failed: {ex.Message}";
            }
        }
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }
}

