         <div class="d-flex justify-content-between align-items-center mb-3">
             <h6 class="mb-0">Reference @Position</h6>
             @if (CanRemove)
             {
                 <button class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
             }
         </div>

         <div class="row g-3">
             <div class="col-md-6">
                 <label class="form-label">Name</label>
                 <input class="form-control" value="@Name"
                        @onchange="e => { Name = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
             </div>
             <div class="col-md-6">
                 <label class="form-label">Relationship</label>
                 <input class="form-control" value="@Relationship"
                        @onchange="e => { Relationship = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
             </div>
             <div class="col-md-6">
                 <label class="form-label">Email</label>
                 <input type="email" class="form-control" value="@Email"
                        @onchange="e => { Email = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
             </div>
             <div class="col-md-6">
                 <label class="form-label">Phone</label>
                 <input type="tel" class="form-control" value="@Phone"
                        @onchange="e => { Phone = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
             </div>
         </div>
     </div>
 </div>

 @code {
     [Parameter] public int Position { get; set; }
     [Parameter] public string Name { get; set; } = "";
     [Parameter] public string Relationship { get; set; } = "";
     [Parameter] public string Email { get; set; } = "";
     [Parameter] public string Phone { get; set; } = "";
     [Parameter] public bool CanRemove { get; set; }
     [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }
     [Parameter] public EventCallback OnRemove { get; set; }

     private void NotifyChanged()
     {
         OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
     }

     public record ReferenceData(string Name, string Relationship, string Email, string Phone);
 }

