}", "new_str": "<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="mb-0">Position @Position</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="HandleRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <input class="form-control" @bind="Company" @bind:after="NotifyChanged" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <input class="form-control" @bind="Title" @bind:after="NotifyChanged" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <input type="date" class="form-control" @bind="StartDate" @bind:after="NotifyChanged" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" @bind="EndDate" @bind:after="NotifyChanged"
                       disabled="@IsCurrent" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" @bind="IsCurrent" @bind:after="HandleCurrentChanged" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @bind="Description" @bind:after="NotifyChanged"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Position { get; set; }
    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private Task HandleRemove() => OnRemove.InvokeAsync();

    private Task HandleCurrentChanged()
    {
        if (IsCurrent) EndDate = null;
        return NotifyChanged();
    }

    private Task NotifyChanged() =>
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, IsCurrent ? null : EndDate, IsCurrent, Description));

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}"}

